#
# Fails when the generated chart lost a v1.0.1 fix (runs in `make verify`; dist/ is regenerated by the helm
# plugin, never edited by hand):
#   - B1: the metrics NetworkPolicy has an ingress rule without `from` (the metrics port open to every
#     namespace), or the separate health-probe policy is missing;
#   - B2: the PrometheusRule does not use .Values.prometheus.labels (run `make chart-patch`).
set -euo pipefail

t=dist/chart/templates
fail=0

metrics=$t/network-policy/allow-metrics-traffic.yaml
# Each ingress rule is a list item; one that starts with `ports:` instead of `from:` admits every source.
if grep -qE '^[[:space:]]*- ports:' "$metrics"; then
  echo "check-chart: $metrics has an ingress rule without 'from' (metrics port open to all namespaces)" >&2
  fail=1
fi

probes=$t/network-policy/allow-health-probes.yaml
if ! grep -qE 'port: 8081' "$probes" 2>/dev/null; then
  echo "check-chart: $probes is missing or does not open port 8081; regenerate the chart" >&2
  fail=1
fi

if ! grep -q '\.Values\.prometheus\.labels' "$t/extras/alerts.yaml"; then
  echo "check-chart: $t/extras/alerts.yaml has no .Values.prometheus.labels; run 'make chart-patch'" >&2
  fail=1
fi

[ "$fail" -eq 0 ] || exit 1
echo "check-chart: NetworkPolicies and PrometheusRule labels are as expected"
